import{c as a,Q as n,j as s,m as l}from"./chunks/framework.DOi4mjdC.js";const e="/assets/Matmul%E9%BB%98%E8%AE%A4%E6%90%AC%E5%85%A5A%E7%9F%A9%E9%98%B5%E7%A4%BA%E6%84%8F%E5%9B%BE.COvHpCVz.png",g=JSON.parse('{"title":"MatmulCallBackFunc","description":"","frontmatter":{},"headers":[{"level":1,"title":"MatmulCallBackFunc","slug":"matmulcallbackfunc"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/高阶API/矩阵计算/Matmul-Kernel侧接口/MatmulCallBackFunc.md","filePath":"api/SIMD-API/高阶API/矩阵计算/Matmul-Kernel侧接口/MatmulCallBackFunc.md"}'),i={name:"api/SIMD-API/高阶API/矩阵计算/Matmul-Kernel侧接口/MatmulCallBackFunc.md"};function p(r,t,o,c,d,u){return n(),s("div",null,[...t[0]||(t[0]=[l('<h1 id="matmulcallbackfunc" tabindex="-1">MatmulCallBackFunc <a class="header-anchor" href="#matmulcallbackfunc" aria-label="Permalink to &quot;MatmulCallBackFunc&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>√</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>√</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>x</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>x</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>x</td></tr><tr><td>Kirin X90</td><td>√</td></tr><tr><td>Kirin 9030</td><td>x</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>模板参数MatmulCallBackFunc支持用户定制化Matmul的A矩阵、B矩阵及C矩阵的搬入搬出功能，如非连续搬入或针对搬出设置不同的数据片段间隔等。具体方式为：用户根据实际需要，实现一个或多个自定义的搬运函数，定义Matmul对象时，通过模板参数MatmulCallBackFunc，传入实现的搬运函数的函数指针，传入的函数指针会替换Matmul流程中默认的搬运函数。</p><p>MatmulCallBackFunc中包含3个可由用户自定义的回调函数接口，即用户可配置3个函数指针。3个函数指针分别为C矩阵从CO1拷贝到GM、A矩阵从GM拷贝到A1、B矩阵从GM拷贝到B1的回调函数指针。3个函数指针的位置固定，不使用自定义搬运函数的函数指针位置需要设为空指针。各个功能回调函数接口定义及参数释义见<a href="#table10989848113111">表1 MatmulCallBackFunc回调函数接口及参数说明</a>。每个回调函数实现矩阵搬运中单个基本块（A矩阵基本块baseM * baseK、B矩阵基本块baseK * baseN、C矩阵基本块baseM * baseN）的搬运策略，无法对整块内存空间进行管理。Matmul默认的搬运函数实现单核上单个基本块的搬运，搬运的基本块大小是固定的，在完整的Matmul计算过程中，多次调用搬运函数，对连续排布的基本块按顺序逐个搬运，以搬入A矩阵的过程为例，示意图如下。</p><p><strong>图 1</strong> Matmul默认搬入A矩阵示意图<br><img src="'+e+`" alt="" title="Matmul默认搬入A矩阵示意图"></p><p><strong>表 1</strong> MatmulCallBackFunc回调函数接口及参数说明</p><table tabindex="0"><thead><tr><th>回调函数功能</th><th>回调函数接口</th><th>参数说明</th></tr></thead><tbody><tr><td>可自定义设置不同的搬出数据片段数目等参数，实现将Matmul计算结果从CO1搬出到GM的功能</td><td>void DataCopyOut(const <strong>gm</strong> void *gm, const LocalTensor&lt;int8_t&gt; &amp;co1Local, const void *dataCopyOutParams, const uint64_t tilingPtr, const uint64_t dataPtr)</td><td>gm：输出的GM地址。 co1Local: CO1上的计算结果。 dataCopyOutParams：Matmul定义的DataCopyOutParams结构体指针，具体定义如下方代码所示，供用户参考使用。 tilingPtr: 用户使用SetUserDefInfo设置的tiling参数地址。 dataPtr: 用户使用SetSelfDefineData设置的计算数据地址。</td></tr><tr><td>可自定义左矩阵搬入首地址、搬运块位置、搬运块大小，实现左矩阵从GM搬入L1的功能</td><td>void CopyA1(const LocalTensor&lt;int8_t&gt; &amp;aMatrix, const <strong>gm</strong> void *gm, int row, int col, int useM, int useK, const uint64_t tilingPtr, const uint64_t dataPtr)</td><td>aMatrix: 目标L1Buffer地址。 gm：左矩阵GM首地址。 row、col：搬运块在M、K方向的索引，即在M、K方向上搬运块的序号，序号从0开始。 useM、useK：搬运块M、K方向大小，单位为元素个数。通过row、col和useM、useK计算出该搬运块左上角在左矩阵中的地址偏移。 tilingPtr: 用户使用SetUserDefInfo设置的tiling参数地址。 dataPtr: 用户使用SetSelfDefineData设置的计算数据地址。</td></tr><tr><td>可自定义右矩阵搬入首地址、搬运块位置、搬运块大小，实现右矩阵从GM搬入L1的功能</td><td>void CopyB1(const LocalTensor&lt;int8_t&gt; &amp;bMatrix, const <strong>gm</strong> void *gm, int row, int col, int useK, int useN, const uint64_t tilingPtr, const uint64_t dataPtr)</td><td>bMatrix: 目标L1Buffer地址。 gm：右矩阵GM首地址。 row、col：搬运块在K、N方向的索引，即在K、N方向上搬运块的序号，序号从0开始。 useK、useN：搬运块K、N方向大小，单位为元素个数。通过row、col和useK、useN计算出该搬运块左上角在右矩阵中的地址偏移。 tilingPtr: 用户使用SetUserDefInfo设置的tiling参数地址。 dataPtr: 用户使用SetSelfDefineData设置的计算数据地址。</td></tr></tbody></table><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>struct DataCopyOutParams {</span></span>
<span class="line"><span>    uint16_t cBurstNum; //传输数据片段数目</span></span>
<span class="line"><span>    uint16_t burstLen; //连续传输数据片段长度</span></span>
<span class="line"><span>    uint16_t srcStride;//源tensor相邻连续数据片段间隔</span></span>
<span class="line"><span>    uint32_t dstStride; // 目的tensor相邻连续数据片段间隔</span></span>
<span class="line"><span>    uint16_t oriNSize; // NZ转ND时，源tensorN方向大小</span></span>
<span class="line"><span>    bool enUnitFlag; // 是否使能UnitFlag</span></span>
<span class="line"><span>    uint64_t quantScalar; // 量化场景下量化Scalar的值</span></span>
<span class="line"><span>    uint64_t cbufWorkspaceAddr; //量化场景下量化Tensor地址</span></span>
<span class="line"><span>}</span></span></code></pre></div><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><p>无</p><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>//用户自定义回调函数</span></span>
<span class="line"><span>void DataCopyOut(const __gm__ void *gm, const LocalTensor&lt;int8_t&gt; &amp;co1Local, const void *dataCopyOutParams, const uint64_t tilingPtr, const uint64_t dataPtr);</span></span>
<span class="line"><span>void CopyA1(const LocalTensor&lt;int8_t&gt; &amp;aMatrix, const __gm__ void *gm, int row, int col, int useM, int useK, const uint64_t tilingPtr, const uint64_t dataPtr);</span></span>
<span class="line"><span>void CopyB1(const LocalTensor&lt;int8_t&gt; &amp;bMatrix, const __gm__ void *gm, int row, int col, int useK, int useN, const uint64_t tilingPtr, const uint64_t dataPtr);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>AscendC::Matmul&lt;aType, bType, cType, biasType, CFG_NORM, MatmulCallBackFunc&lt;DataCopyOut, CopyA1, CopyB1&gt;&gt; mm;</span></span>
<span class="line"><span>REGIST_MATMUL_OBJ(&amp;pipe, GetSysWorkSpacePtr(), mm, &amp;tiling);</span></span>
<span class="line"><span>uint64_t tilingPtr = reinterpret_cast&lt;uint64_t&gt;(tiling);</span></span>
<span class="line"><span>mm.SetUserDefInfo(tilingPtr); // 设置算子tiling地址，用于回调函数使用</span></span>
<span class="line"><span>GlobalTensor&lt;SrcT&gt; dataGM; // 保存有回调函数需使用的计算数据的GM</span></span>
<span class="line"><span>uint64_t dataGMPtr = reinterpret_cast&lt;uint64_t&gt;(dataGM.address_);</span></span>
<span class="line"><span>mm.SetSelfDefineData(dataGMPtr); // 设置需要的计算数据或在GM上存储的数据地址等信息，用于回调函数使用</span></span>
<span class="line"><span>mm.SetTensorA(gmA);</span></span>
<span class="line"><span>mm.SetTensorB(gmB);</span></span>
<span class="line"><span>if (tiling.isBias) {</span></span>
<span class="line"><span>    mm.SetBias(gmBias);</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>mm.IterateAll();</span></span>
<span class="line"><span>mm.End();</span></span></code></pre></div>`,14)])])}const _=a(i,[["render",p]]);export{g as __pageData,_ as default};
